package io.github.ilyaandreev05.eventsoundstudio.config;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/** Small, lossless fixes for known persisted-default mistakes. */
public final class ConfigMigrator {
    private ConfigMigrator(){}

    /** Rewrites the exact malformed letter-group generated by early Event Sound Studio defaults. */
    public static boolean migrateKnownDefaults(Map<String,Object> root){
        Object rawGroups=root.get("groups");if(!(rawGroups instanceof List<?> groups))return false;
        List<String> oldMembers=new ArrayList<>();for(char c='A';c<='Z';c++)oldMembers.add("KEY_A"+c);
        for(Object item:groups)if(item instanceof Map<?,?> raw&&"builtin.letters".equals(raw.get("id"))&&oldMembers.equals(raw.get("members"))){
            @SuppressWarnings("unchecked") Map<String,Object> group=(Map<String,Object>)raw;group.put("members",DefaultConfig.BUILTIN_GROUPS.get("builtin.letters"));return true;
        }
        return false;
    }
}
